@startuml

class Animal {
  + id : int
  + name : string
  + breed : string
}

class Owner {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class Physician {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class Appointment {
  + start_date_time : datetime
}

class Condition {
  + common_name : string
  + scientific_name : string
}

class Breed {
  + name : string
}

Owner "0..1" -- "*" Animal : owns
Animal "1" -- "*" Appointment : attended_by
Owner "1" -- "*" Appointment : attended_by
Physician "1" -- "*" Appointment : responsible_for
Breed "1" -- "*" Animal : describes
Breed "1" -- "*" Condition : has_common
Condition "*" -- "*" Breed : common_to

@enduml

